begin;

insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata)
values
(
  'social-studies','a1-family-functions-sources','a1-individual-family','1–2. Family Functions and Evaluating Sources','Understand what families do in Caribbean society and learn how to judge sources before building a sound definition of family.',10,true,
  '{"syllabus":{"section":"A","part":"i","objectives":["1","2"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Describe the major functions of the family in contemporary Caribbean society.","Explain how families meet economic, emotional and psychological needs.","Evaluate sources using accuracy, authority, currency, objectivity, coverage and relevance.","Use evidence from reliable sources to form a sensible definition of family."],"introduction":"Family is one of the first groups through which most people experience care, rules, responsibility and belonging. Caribbean families do not all look the same, but they perform important functions. Social Studies also expects you to judge information carefully instead of accepting the first definition you find online.","sections":[{"title":"What a family does","paragraphs":["The family is a social group whose members are connected through relationships such as birth, marriage, union, adoption or long-term caregiving. A useful definition should be broad enough to recognise real family life without pretending that every household has the same structure.","CXC focuses on four major functions: procreation, socialisation, economic support, and the satisfaction of emotional and psychological needs."],"bullets":["Procreation: families may provide the setting in which children are born and raised.","Socialisation: children learn language, manners, values, beliefs, expectations and everyday behaviour.","Economic support: family members budget, save, use credit carefully, practise thrift and pay for needs such as food, housing, transport and school.","Emotional and psychological support: affection, belonging, encouragement, security and guidance help members cope with challenges."]},{"title":"A Caribbean home example","paragraphs":["Imagine a household in St Catherine where a grandmother supervises homework while a parent works an evening shift. An older sibling prepares dinner and the adults plan how to pay the light bill and school expenses. Socialisation, economic support and emotional care are happening together. One function does not have to be performed by one person.","Government and community institutions can assist families through schools, health services, social protection and child-care programmes, but this does not remove the family''s own responsibilities."]},{"title":"How to judge a source","bullets":["Accuracy: Can important claims be checked against evidence?","Authority: Who created the information, and are they qualified or responsible for the subject?","Currency: Is the information recent enough for the question being studied?","Objectivity: Is the source trying mainly to inform, or is it pushing one side without fair evidence?","Coverage: Does it deal with the topic adequately, or leave out important parts?","Relevance: Does it actually help answer your research question?"]},{"title":"Building a definition instead of copying one","paragraphs":["A strong student compares more than one reliable source, identifies the common ideas, notices differences, and then writes a clear definition in his or her own words. This is a research skill that will also matter in the SBA.","For example, a dictionary may give a short definition, a CXC text may emphasise the family as a social group, and a statistical agency may define a household differently because it is counting people. The purpose of a source affects the definition it uses."]}],"keyPoints":["Families perform procreative, socialising, economic, emotional and psychological functions.","Socialisation is the process through which people learn the norms, values and behaviours expected in society.","A source should be judged for accuracy, authority, currency, objectivity, coverage and relevance.","A good Social Studies definition is supported by reliable evidence and suited to the context."],"workedExample":{"title":"Which source would you trust?","prompt":"A student finds a five-year-old government statistical report, an anonymous social-media post and a current university research article about changing household patterns.","steps":["Check who produced each source.","Check whether the information can be verified.","Check the date and purpose.","Use the strongest sources together rather than relying on the anonymous post."],"answer":"The government report and current university article are stronger starting points. The social-media post may suggest an issue to investigate, but it needs verification."},"summary":"Know the family functions, but also understand how they appear in real homes. When a question asks you to evaluate information, explain why a source is dependable or limited. Do not simply say that one source is ''better''.","flashcards":[{"front":"What is socialisation in the family?","back":"Learning society’s norms, values and expected behaviour through family life."},{"front":"Name four major functions of the family.","back":"Procreation, socialisation, economic support, and emotional/psychological support."},{"front":"What does source authority mean?","back":"The creator has suitable expertise, responsibility or credibility for the topic."},{"front":"What does source currency mean?","back":"The information is recent enough for the question being studied."},{"front":"What does source objectivity examine?","back":"Whether information is presented fairly rather than distorted by bias."},{"front":"Why compare several sources?","back":"To verify claims, see different perspectives and build a better-supported conclusion."}],"interactiveModels":[{"id":"a1-source-detective","type":"social-studies","mode":"evidence","title":"Source Detective","subtitle":"Judge sources the way a careful Social Studies researcher would.","items":[{"type":"Official statistics","title":"National statistical agency census table","description":"Published by the official statistics agency with date, definitions and methodology.","rating":"Strong","explanation":"It has clear authority and methods and is directly relevant to population or household data."},{"type":"Social media","title":"Anonymous viral post","description":"Claims that ''almost every Caribbean family is now a single-parent household'' but gives no source.","rating":"Weak","explanation":"The claim is broad, anonymous and unsupported. It must be verified before use."},{"type":"News interview","title":"Interview with one parent","description":"A named parent describes the challenges in one household.","rating":"Use with caution","explanation":"It is useful primary evidence about one experience, but one household cannot represent the whole Caribbean."}]}]}}'::jsonb
),
(
  'social-studies','a1-family-types-unions','a1-individual-family','3. Family Types, Relations, Unions and Respect','Compare family structures and unions, interpret family relationships and practise respectful Social Studies language.',20,true,
  '{"syllabus":{"section":"A","part":"i","objectives":["3a","3b"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Identify and compare nuclear, extended, sibling and single-parent families.","Distinguish visiting, common-law/consensual and legal marriage unions.","Interpret simple family-tree relationships.","Demonstrate respect and tolerance when discussing different family structures."],"introduction":"There is no single Caribbean family pattern. Students may live with parents, grandparents, siblings or other caregivers. Social Studies asks you to describe and compare family structures accurately, without treating one structure as automatically superior to another.","sections":[{"title":"Family types","bullets":["Nuclear family: parent or parents and their child or children living as a family unit.","Extended family: the family network includes relatives beyond parents and children, such as grandparents, aunts, uncles or cousins.","Sibling household: brothers and/or sisters live together without a parent in the household.","Single-parent family: one parent has the main day-to-day responsibility for the child or children."]},{"title":"Unions","bullets":["Visiting relationship: partners maintain separate households and visit each other rather than living together permanently.","Consensual or common-law union: partners live together in a marriage-like relationship without a formal legal marriage.","Legal marriage: a marriage recognised under the law after the required legal procedures.","Civil and legal recognition can vary by jurisdiction, so exam answers should distinguish the social form of a union from its precise legal status."]},{"title":"Family relations and the family tree","paragraphs":["A family tree shows relationships across generations. Read it carefully before naming a relationship. If Marcia is the mother of Andre and Andre is the father of Leila, then Marcia is Leila''s grandmother. Do not guess from age or surname alone."]},{"title":"Respect is part of the objective","paragraphs":["A Social Studies answer should describe a family form without insulting or stereotyping the people in it. Family structure alone does not tell you whether a home is caring, stable, wealthy, poor, effective or ineffective. Those conclusions require evidence."]}],"keyPoints":["Family type describes structure, while union describes the relationship between partners.","Extended families can provide wider networks of care and support.","A family tree represents kinship relationships across generations.","Respectful analysis separates evidence from stereotypes."],"summary":"Learn the defining features of each family type and union, then practise applying them to short scenarios. In comparison questions, state a real similarity or difference instead of merely listing definitions.","flashcards":[{"front":"What is a nuclear family?","back":"Parent or parents and their child or children living as a family unit."},{"front":"What is an extended family?","back":"A family network that includes relatives beyond parents and children."},{"front":"What is a sibling household?","back":"A household formed mainly by brothers and/or sisters without a parent present."},{"front":"What is a visiting relationship?","back":"Partners maintain separate households and visit rather than live together permanently."},{"front":"What is a common-law or consensual union?","back":"Partners live together in a marriage-like relationship without formal legal marriage."},{"front":"Why avoid stereotypes about family types?","back":"Structure alone does not prove how caring, stable or effective a family is."}],"interactiveModels":[{"id":"a1-family-classifier","type":"social-studies","mode":"classify","title":"Caribbean Family Classifier","categories":["Nuclear","Extended","Sibling household","Single-parent"],"items":[{"label":"Keisha lives with her mother and two brothers.","category":"Single-parent","explanation":"One parent has the main household parenting role."},{"label":"Dario lives with both parents and his younger sister.","category":"Nuclear","explanation":"Parents and children form the household unit."},{"label":"Asha lives with her parents, grandmother and aunt.","category":"Extended","explanation":"Relatives beyond parents and children are part of the household."},{"label":"Three adult sisters share a home after their parents migrate.","category":"Sibling household","explanation":"The household is formed by siblings."}]}]}}'::jsonb
),
(
  'social-studies','a1-family-roles-change-research','a1-individual-family','4–5. Family Roles, Changing Responsibilities and Research Questions','Examine traditional and contemporary family roles, why they change, and how to frame researchable questions.',30,true,
  '{"syllabus":{"section":"A","part":"i","objectives":["4","5a","5b"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Examine roles and responsibilities of adults and children in Caribbean families.","Explain causes and effects of changing family roles.","Distinguish a feasible, specific research question from a vague one.","Avoid assuming that household work or earning roles belong naturally to one gender."],"introduction":"Family roles are learned and negotiated. They are affected by work, education, technology, beliefs, income and the needs of family members. A modern Social Studies answer should explain change, not simply label a task as ''male'' or ''female''.","sections":[{"title":"Roles and responsibilities","paragraphs":["Adults may provide income, care, guidance, discipline, household management and emotional support. Children also have age-appropriate responsibilities such as caring for belongings, helping with household tasks, respecting rules and contributing to family life.","Roles can be shared. A father can cook and supervise homework. A mother can be the main income earner. A grandparent may be the main caregiver."]},{"title":"Why roles change","bullets":["Improved educational opportunities and changing rights and status of women.","Changes in employment patterns and the cost of living.","Household technology that changes the time needed for domestic work.","Changing leisure patterns, social expectations and attitudes.","Migration, single parenting and other changes in household composition."]},{"title":"Possible effects of changing roles","bullets":["Greater sharing of household responsibilities.","Increased independence and confidence for family members.","Role conflict when work, study and family demands compete.","Tension when people expect traditional roles but household realities have changed.","Changes in how men and women understand identity and responsibility."]},{"title":"Turning curiosity into a research question","paragraphs":["A research question should be feasible, researchable and specific. ''Families today are bad'' is not a research question. ''How does evening-shift employment affect homework supervision among parents of Grade 10 students at School X?'' is much stronger because it identifies a clear issue and group.","Avoid questions that already assume the answer. Research is meant to investigate, not to prove your opinion."]}],"keyPoints":["Roles are expected patterns of behaviour linked to a person''s position in the family.","Role conflict occurs when responsibilities compete or interfere with each other.","Family roles change with social, economic, educational and technological conditions.","A strong research question is feasible, researchable, specific and neutral."],"summary":"For exam questions, connect a cause of changing roles to a clear effect. For research, narrow the issue until the question can realistically be investigated using evidence.","flashcards":[{"front":"What is role conflict?","back":"When one responsibility interferes with another responsibility a person must perform."},{"front":"Give one cause of changing family roles.","back":"Examples include education, employment, technology or changing gender expectations."},{"front":"What makes a research question feasible?","back":"It can realistically be investigated with the available time, access and resources."},{"front":"What makes a research question specific?","back":"It clearly identifies the issue, variables or group being studied."},{"front":"Why avoid leading research questions?","back":"They push toward a preferred answer and can bias the investigation."}],"interactiveModels":[{"id":"a1-research-question-check","type":"social-studies","mode":"choice","title":"Research Question Workshop","items":[{"prompt":"Which is the strongest research question?","choices":["Why are modern families failing?","How does after-school employment affect study time among Grade 11 students at School X?","Are parents irresponsible these days?","Why is technology bad for families?"],"correctIndex":1,"explanation":"It identifies a relationship, a target group and a setting without assuming the answer."},{"prompt":"What is the main weakness in: ''Why do lazy teenagers refuse to help at home?''","choices":["It has no verb","It is too short","It uses biased language and assumes the cause","It is about family roles"],"correctIndex":2,"explanation":"The wording labels the group and assumes a reason before research has been done."},{"prompt":"Which question is most feasible for a school SBA?","choices":["How do all Caribbean families divide chores?","How do 30 Grade 10 students in my school describe the sharing of household chores?","What causes every family conflict in the world?","Will family roles change by 2050?"],"correctIndex":1,"explanation":"A defined school sample is realistic to investigate."}]}]}}'::jsonb
),
(
  'social-studies','a1-parenthood-questionnaires','a1-individual-family','6–7. Preparing for Parenthood and Designing Questionnaires','Study readiness for parenthood while learning how to design clear, unbiased questionnaires.',40,true,
  '{"syllabus":{"section":"A","part":"i","objectives":["6","7"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Explain physical, economic, emotional and psychological readiness for parenthood.","Explain why readiness involves more than age.","Design short, clear, relevant and unbiased questionnaire items.","Arrange questionnaire items in a logical sequence."],"introduction":"Parenthood changes everyday life. CSEC treats preparation for parenthood as physical, economic, emotional and psychological readiness. This topic also provides a practical research setting for learning questionnaire design.","sections":[{"title":"Four areas of readiness","bullets":["Physical readiness: health, access to appropriate health care and the physical demands of pregnancy and caregiving.","Economic readiness: the ability to plan for food, housing, clothing, health care, child care, transport and education.","Emotional readiness: the capacity to give affection, manage frustration, communicate and respond to a child''s needs.","Psychological readiness: realistic expectations, maturity, decision-making and the ability to cope with long-term responsibility."]},{"title":"Readiness is connected","paragraphs":["A person can have an income and still be emotionally unprepared. Another person may be loving and committed but face serious financial strain. Good analysis looks at the areas together rather than reducing parenthood to one factor."]},{"title":"Writing a good questionnaire","bullets":["Use simple, familiar words.","Keep each question short, clear and specific.","Ask about one issue at a time.","Avoid leading or biased wording.","Do not make questions unnecessarily difficult or time-consuming.","Arrange questions in a logical order.","Include only questions relevant to the research topic."]},{"title":"Spot the problem","paragraphs":["''Don''t you agree that responsible parents should save money and spend more time with children?'' is a poor question. It is leading and asks about two issues at once. Better questions separate saving from time spent with children and offer neutral response choices."]}],"keyPoints":["Parenthood readiness includes physical, economic, emotional and psychological factors.","A questionnaire is a data-collection instrument, not a speech or argument.","One questionnaire item should normally deal with one issue.","Biased wording can reduce the validity of the data collected."],"summary":"In the exam and SBA, be able to explain why a questionnaire item is weak and rewrite it. Clear research instruments lead to better evidence.","flashcards":[{"front":"Name four areas of readiness for parenthood.","back":"Physical, economic, emotional and psychological readiness."},{"front":"Why ask one issue per questionnaire item?","back":"So respondents know exactly what they are answering and data are easier to interpret."},{"front":"What is a leading question?","back":"A question worded to push respondents toward a preferred answer."},{"front":"Why should questionnaire items be relevant?","back":"Irrelevant items waste time and do not help answer the research question."},{"front":"Why use a logical question sequence?","back":"It makes the instrument easier to follow and reduces confusion."}],"interactiveModels":[{"id":"a1-questionnaire-doctor","type":"social-studies","mode":"choice","title":"Questionnaire Doctor","items":[{"prompt":"Which item is best written?","choices":["Good parents always budget, right?","How often does your household prepare a monthly budget?","Do you save money and spend wisely?","Why don''t families save enough?"],"correctIndex":1,"explanation":"It is neutral, specific and asks about one issue."},{"prompt":"What is wrong with ''Do you exercise and eat healthy food every day?''","choices":["It is too formal","It asks two issues at once","It has no response options","Nothing"],"correctIndex":1,"explanation":"Exercise and diet should be asked separately."},{"prompt":"Which item is most neutral?","choices":["How harmful is social media to family life?","Do responsible parents limit phones?","How many hours per day do you use social media at home?","Why do phones destroy communication?"],"correctIndex":2,"explanation":"It gathers measurable information without assuming harm."}]}]}}'::jsonb
),
(
  'social-studies','a1-effective-parenting','a1-individual-family','8. Effective Parenting','Apply communication, discipline, problem-solving, nutrition, money management and decision-making to realistic parenting situations.',50,true,
  '{"syllabus":{"section":"A","part":"i","objectives":["8"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Identify qualities associated with effective parenting.","Explain why discipline is different from uncontrolled punishment.","Apply communication and problem-solving skills to family situations.","Connect parenting choices to socialisation and child development."],"introduction":"Effective parenting is not about being perfect. It is about consistently meeting responsibilities, communicating, setting reasonable boundaries and helping children develop the skills they need to function in society.","sections":[{"title":"Core qualities","bullets":["Problem-solving: identify the issue, consider options and choose a sensible response.","Communication: listen as well as speak; explain expectations clearly.","Socialising skills: teach values, manners, cooperation and responsible behaviour.","Disciplinary skills: set fair boundaries and use consistent, appropriate consequences.","Knowledge of good nutrition: support healthy growth and habits.","Love and warmth: provide affection, encouragement and emotional security.","Money management: plan spending and priorities.","Decision-making: consider consequences before acting."]},{"title":"Discipline should teach","paragraphs":["Discipline is most effective when the child understands the rule, the consequence is proportionate and the adult is consistent. Anger by itself is not a parenting strategy. The goal is to develop self-control and responsible behaviour."]},{"title":"A Caribbean example","paragraphs":["A Form 3 student in Montego Bay repeatedly comes home late without contacting the caregiver. An effective response may include listening to the reason, restating the agreed time, discussing safety, setting a clear consequence and deciding how the student should communicate if delayed. This combines communication, discipline and problem-solving."]}],"keyPoints":["Effective parenting combines care with responsibility and clear guidance.","Communication includes listening, explaining and checking understanding.","Discipline should guide behaviour through fair and consistent boundaries.","Money management and nutrition are practical parenting skills, not separate from care."],"summary":"When a question gives a parenting scenario, name the relevant quality and explain how using it could improve the situation.","flashcards":[{"front":"What is the purpose of effective discipline?","back":"To guide behaviour and build self-control through fair, consistent boundaries."},{"front":"How does communication support parenting?","back":"It helps family members listen, explain expectations and resolve problems."},{"front":"Why is money management a parenting skill?","back":"Families must plan limited income to meet children''s needs and other priorities."},{"front":"How does socialisation relate to parenting?","back":"Parents and caregivers help children learn values, behaviour and social expectations."}],"interactiveModels":[{"id":"a1-parenting-scenarios","type":"social-studies","mode":"choice","title":"Parenting in Practice","items":[{"context":"A 13-year-old''s grades suddenly fall and she has become unusually quiet.","prompt":"Which response best shows effective parenting?","choices":["Assume laziness and punish immediately","Listen privately, ask what changed, then plan support and expectations","Post about it in the family group chat","Ignore it until the report card"],"correctIndex":1,"explanation":"Listening first gathers information and makes problem-solving more effective."},{"context":"Two siblings keep arguing over one tablet needed for homework.","prompt":"Which skill is most useful first?","choices":["Money management only","Problem-solving and communication","Ignoring the argument","Comparing the children"],"correctIndex":1,"explanation":"The family can identify the need, agree on a schedule and set fair rules."}]}]}}'::jsonb
),
(
  'social-studies','a1-social-issues-research','a1-individual-family','9. Contemporary Social Issues, Solutions and Interview Skills','Analyse family-related social issues using cause-effect-solution reasoning and ethical research skills.',60,true,
  '{"syllabus":{"section":"A","part":"i","objectives":["9a","9b","9c","9d"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Examine causes and effects of contemporary social issues affecting Caribbean family life.","Propose realistic strategies for addressing social issues.","Justify a proposed solution using a clear link to the problem.","Design an interview schedule suitable for gathering sensitive social information."],"introduction":"Social issues are not just lists to memorise. CSEC expects you to explain causes, effects and responses. Good answers also avoid blaming vulnerable people. Many issues arise from a combination of individual, family, economic, institutional and community factors.","sections":[{"title":"Issues in the syllabus","paragraphs":["Examples include teenage pregnancy, child abandonment, sibling rivalry, divorce or separation, generation gaps, substance abuse, juvenile delinquency, sexually transmitted infections, child abuse, poverty, desertion, suicide, incest, domestic violence, trafficking in persons, and the abuse or neglect of elderly people, persons with mental illness and persons with special needs.","Some of these topics are sensitive. In research and discussion, protect privacy, avoid sensational language and do not pressure people to disclose personal trauma."]},{"title":"Think in chains: cause → effect → response","paragraphs":["Suppose a household experiences long-term unemployment. Reduced income may increase difficulty meeting basic needs. Stress may increase family conflict. A response could combine employment support, financial guidance and counselling. The strongest answer explains why each response addresses a specific part of the problem."]},{"title":"A solution must fit the cause","bullets":["Education and training can improve knowledge or employability.","Financial support can help families meet urgent material needs.","Employment opportunities can reduce income insecurity.","Counselling can support communication and coping.","Law enforcement is relevant when laws are being broken and protection is needed.","Social services and institutions can provide specialised support.","Family and community support can reduce isolation and share care responsibilities."]},{"title":"Interview schedules","paragraphs":["An interview schedule is a planned set of questions used by an interviewer. Questions should be clear, neutral, relevant and sequenced logically. For sensitive topics, begin with less intrusive questions, explain the purpose, protect confidentiality where promised, and let respondents decline inappropriate questions.","The interviewer may ask planned follow-up questions, but should avoid changing the meaning of questions in ways that make responses impossible to compare."]}],"keyPoints":["Social issues usually have multiple causes and effects.","A recommendation is stronger when it directly addresses an identified cause or effect.","Sensitive research requires respect, privacy and neutral language.","An interview schedule provides consistency while allowing the interviewer to gather detailed responses."],"summary":"Use a cause-effect-solution structure. Do not merely say ''government should help''. State what should be done, by whom, and why it fits the problem.","flashcards":[{"front":"What makes a solution well justified?","back":"It directly addresses an identified cause or effect and explains why it should help."},{"front":"What is an interview schedule?","back":"A planned set of questions used by an interviewer to collect consistent information."},{"front":"Why use neutral wording in sensitive research?","back":"To reduce bias, protect respondents and improve the quality of information."},{"front":"Give one institutional response to a family social issue.","back":"Examples: counselling, social services, education, financial support or law enforcement."},{"front":"Why avoid blaming language in social-issue analysis?","back":"It can distort causes, stigmatise people and weaken objective analysis."}],"interactiveModels":[{"id":"a1-cause-effect-solution","type":"social-studies","mode":"classify","title":"Cause, Effect or Response?","categories":["Possible cause","Possible effect","Possible response"],"items":[{"label":"Loss of household income after prolonged unemployment","category":"Possible cause"},{"label":"Difficulty paying for food, transport and school expenses","category":"Possible effect"},{"label":"Job-skills training linked to available vacancies","category":"Possible response"},{"label":"Confidential family counselling","category":"Possible response"},{"label":"Persistent conflict within the household","category":"Possible effect"}]}]}}'::jsonb
),
(
  'social-studies','a1-family-law','a1-individual-family','10. Laws that Protect the Family','Understand why laws concerning inheritance, child care, separation, divorce and domestic violence matter to family welfare.',70,true,
  '{"syllabus":{"section":"A","part":"i","objectives":["10"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Describe the purposes of laws relating to inheritance, child care, legal separation, divorce and domestic violence.","Explain how laws can protect rights and set responsibilities.","Distinguish legal protection from personal opinion about a family dispute.","Recognise that detailed procedures vary among Caribbean jurisdictions."],"introduction":"Family relationships are personal, but some disputes affect legal rights, safety, property and responsibilities. Laws create rules for resolving these matters and provide ways for people to seek protection or redress.","sections":[{"title":"Areas named in the syllabus","bullets":["Inheritance: rules about how property or an estate may pass after a person dies.","Child care and maintenance: responsibilities for the welfare and support of children.","Legal separation: formal arrangements when spouses live apart without immediately ending the marriage.","Divorce: the legal ending of a marriage and related arrangements.","Domestic violence: legal measures intended to protect persons from abuse and provide remedies or protective orders where available."]},{"title":"Why laws matter","paragraphs":["The law can clarify rights, responsibilities and procedures when family members cannot resolve a matter privately. It may protect children and vulnerable persons, regulate property and support obligations, and provide an impartial process for disputes.","For CSEC, focus on reasons for legal protection and the social situation involved. Do not assume that the exact procedure is identical in Jamaica, Barbados, Guyana or another territory."]},{"title":"Using examples carefully","paragraphs":["If a question says a parent refuses to contribute to a child''s basic support, explain that child-care or maintenance laws can provide a legal mechanism for enforcing responsibility. Avoid inventing a specific penalty unless the question or source provides it."]}],"keyPoints":["Family law helps define rights, responsibilities and procedures.","Inheritance, child care, separation, divorce and domestic violence are syllabus areas.","Legal rules can differ across Caribbean territories.","A strong answer explains how a law protects a person or resolves a social problem."],"summary":"In exam answers, connect the law to the person or interest it protects. Keep territory-specific legal detail separate unless you have a reliable current source.","flashcards":[{"front":"Why are inheritance laws important?","back":"They provide rules for distributing a deceased person''s estate and protecting legal interests."},{"front":"What is the purpose of child-maintenance law?","back":"To support enforcement of a parent''s legal responsibility toward a child."},{"front":"What is legal separation?","back":"A formal legal arrangement for spouses living apart without necessarily ending the marriage."},{"front":"Why avoid assuming one Caribbean family law applies everywhere?","back":"Detailed laws and procedures differ among jurisdictions."}],"interactiveModels":[{"id":"a1-family-law-purpose","type":"social-studies","mode":"choice","title":"Which Legal Area Fits?","items":[{"prompt":"A dispute arises over how a deceased relative''s property should be distributed.","choices":["Inheritance","Child care","Legal separation","Domestic violence"],"correctIndex":0,"explanation":"Inheritance law addresses rights and procedures connected to a deceased person''s estate."},{"prompt":"A caregiver seeks a legal remedy because a parent refuses financial support for a child.","choices":["Inheritance","Child care/maintenance","Divorce only","Election law"],"correctIndex":1,"explanation":"Child-care and maintenance law addresses responsibilities toward children."},{"prompt":"A person needs legal protection from abuse by an intimate partner.","choices":["Inheritance","Trade law","Domestic violence","Electoral law"],"correctIndex":2,"explanation":"Domestic-violence legislation provides legal avenues for protection and redress."}]}]}}'::jsonb
),
(
  'social-studies','a1-caribbean-culture','a1-individual-family','11–13. Caribbean Cultural Diversity, Heritage and Global Impact','Trace the roots of Caribbean cultural diversity, examine how heritage changes and travels, and assess its global influence.',80,true,
  '{"syllabus":{"section":"A","part":"i","objectives":["11","12","13"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Account for the cultural diversity of the Caribbean region.","Explain how cultural heritage is transmitted and transformed.","Distinguish cultural transmission, creolisation and commercialisation.","Evaluate examples of Caribbean cultural influence beyond the region."],"introduction":"Caribbean culture developed through encounter, survival, resistance, adaptation and exchange. The region includes Indigenous heritage, European colonisation, African enslavement, indentureship and later migration. These histories influenced language, food, religion, music, festivals, family life and much more.","sections":[{"title":"Why the Caribbean is culturally diverse","bullets":["Indigenous peoples established societies and cultural traditions before European colonisation.","European colonisation brought languages, religions, political systems and economic structures.","African people carried cultural knowledge and practices despite the violence of enslavement.","Indentured labourers, especially from India and other parts of Asia, added further traditions and institutions.","Later migration within and beyond the region continued the exchange of ideas and practices."]},{"title":"Cultural forms","paragraphs":["Diversity can be seen in customs, ceremonies, art, craft, language, music, dance, folklore, religions and festivals. In Jamaica, examples may include reggae and dancehall, Revival traditions, Maroon heritage, patois/Creole language practices and foods shaped by several cultural streams. Across the Caribbean, the examples differ, so students should know examples beyond their own territory."]},{"title":"How heritage is transmitted","bullets":["Family members teach language, stories, recipes and customs.","Cultural groups preserve and perform traditions.","Artists reinterpret heritage through music, literature, visual art, dance and theatre.","Schools, museums, religious bodies and other institutions pass knowledge between generations.","Mass media and social media can spread cultural forms rapidly within the region and diaspora."]},{"title":"How culture changes","paragraphs":["Creolisation is the development of new cultural forms through interaction and blending. Commercialisation occurs when cultural products or practices are packaged and sold. Change is not automatically good or bad; Social Studies asks you to evaluate what may be gained, lost or transformed.","Global media and travel can produce cultural influence in both directions. Caribbean culture influences the world while Caribbean societies also absorb ideas from elsewhere."]},{"title":"Caribbean culture on the global stage","paragraphs":["Caribbean influence can be assessed through music, literature, visual art, sport, festivals, food and religion. A strong evaluation identifies evidence of influence and also considers questions such as ownership, representation, commercial benefit and whether cultural meaning changes when a form enters a global market."]}],"keyPoints":["Caribbean cultural diversity reflects Indigenous heritage, colonisation, African enslavement, indentureship and migration.","Cultural heritage is transmitted by families, groups, artists, institutions and media.","Creolisation produces new forms through cultural interaction.","Commercialisation can increase visibility and income but may also change how culture is presented.","Caribbean cultural forms have significant regional and global influence."],"summary":"Do not treat Caribbean culture as one fixed package. Explain its historical roots, the agents that transmit it, the processes that transform it, and specific evidence of influence.","flashcards":[{"front":"Name five roots of Caribbean cultural diversity.","back":"Indigenous peoples, colonisation, African enslavement, indentureship and later migration."},{"front":"What is cultural heritage?","back":"Cultural practices, knowledge and expressions passed between generations."},{"front":"What is creolisation?","back":"The development of new cultural forms through interaction and blending of traditions."},{"front":"What is cultural commercialisation?","back":"Packaging cultural products or practices for sale or economic use."},{"front":"Name three agents of cultural transmission.","back":"Examples: family, cultural groups, artists, institutions or mass/social media."},{"front":"Why can global cultural influence be two-way?","back":"The Caribbean influences other societies while also absorbing ideas from abroad."}],"interactiveModels":[{"id":"a1-culture-processes","type":"social-studies","mode":"classify","title":"How Culture Moves and Changes","categories":["Transmission","Creolisation","Commercialisation","Global influence"],"items":[{"label":"A grandmother teaches grandchildren a traditional recipe.","category":"Transmission"},{"label":"Musicians combine several inherited traditions into a new local style.","category":"Creolisation"},{"label":"A festival design is packaged and sold internationally as a tourism product.","category":"Commercialisation"},{"label":"A Caribbean music style inspires performers in another continent.","category":"Global influence"},{"label":"A school heritage club records elders telling community stories.","category":"Transmission"}]}]}}'::jsonb
)
